components.css:
.ds-payment-result-page{max-width:1440px;margin:auto;padding:56px 48px 80px;font-family:Inter,sans-serif;color:#0f172a;min-height:440px}.ds-payment-result-content{max-width:684px;margin:0 auto}.ds-payment-result-icon{color:#047857;margin-bottom:24px}.ds-payment-result-uncertain{color:#475569}.ds-payment-result-page h1{font-size:34px;font-weight:800;line-height:1.2;letter-spacing:-.035em;color:#064e3b;margin:0 0 16px;text-wrap:balance}.ds-payment-result-page section>p{font-size:14px;line-height:1.8;color:#475569;max-width:65ch;overflow-wrap:anywhere}.ds-payment-result-page .ds-payment-result-order{margin-top:24px;font-weight:600;color:#0f172a}.ds-payment-result-page dl{border-block:1px solid #e2e8f0;margin:32px 0;padding:8px 0}.ds-payment-result-page dl>div{display:flex;justify-content:space-between;align-items:baseline;gap:24px;margin:18px 0;font-size:14px}.ds-payment-result-page dt{color:#475569}.ds-payment-result-page dd{text-align:right;font-weight:600;font-variant-numeric:tabular-nums}.ds-payment-result-page .ds-payment-result-amount{border-top:1px solid #e2e8f0;padding-top:20px;margin-top:24px}.ds-payment-result-amount dd{font-size:28px;letter-spacing:-.025em;color:#047857;white-space:nowrap}.ds-payment-result-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:32px;align-items:center}.ds-payment-result-primary,.ds-payment-result-secondary{min-height:48px;display:inline-flex;justify-content:center;align-items:center;gap:12px;border-radius:8px;padding:12px 18px;font-size:14px;font-weight:600}.ds-payment-result-primary{background:#f59e0b;color:#0f172a}.ds-payment-result-primary:hover{background:#fbbf24}.ds-payment-result-secondary{border:1px solid #047857;color:#047857}.ds-payment-result-secondary:hover{background:#ecfdf5}.ds-payment-result-shopping{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:12px 10px;font-size:14px;color:#047857;text-decoration:underline;text-underline-offset:4px}.ds-payment-result-shopping:hover{color:#064e3b}.ds-payment-result-spinner{animation:ds-payment-verify-spin 1.3s linear infinite}@keyframes ds-payment-verify-spin{to{transform:rotate(360deg)}}
@media(max-width:1199px){.ds-payment-result-page{padding-inline:32px}.ds-payment-result-page h1{font-size:32px}}
@media(max-width:767px){.ds-payment-result-page{padding:40px 20px 56px}.ds-payment-result-page h1{font-size:28px;line-height:1.25}.ds-payment-result-icon{margin-bottom:20px;width:36px;height:36px}.ds-payment-result-page dl>div{gap:16px;font-size:13px}.ds-payment-result-amount dd{font-size:24px}.ds-payment-result-actions{flex-direction:column;align-items:stretch;gap:10px}.ds-payment-result-primary,.ds-payment-result-secondary{width:100%}.ds-payment-result-page dl{margin:28px 0}}
@media(max-width:360px){.ds-payment-result-page{padding-inline:16px}.ds-payment-result-page h1{font-size:26px}.ds-payment-result-amount dt{max-width:45%}.ds-payment-result-amount dd{font-size:23px}}
@media(prefers-reduced-motion:reduce){.ds-payment-result-spinner{animation:none}}

.ds-payment-result-page dd{margin:0}.ds-payment-result-primary{text-decoration:none}.ds-payment-result-actions a:focus-visible{outline:2px solid #047857;outline-offset:3px}
